public final class DisjointSet {
    private final int[] parent;
    private final int[] rank;

    public DisjointSet(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("Set size cannot be negative.");
        }

        parent = new int[size];
        rank = new int[size];

        for (int vertex = 0; vertex < size; vertex++) {
            parent[vertex] = vertex;
            rank[vertex] = 1;
        }
    }

    public boolean unionIfSeparate(int first, int second) {
        int firstRoot = find(first);
        int secondRoot = find(second);

        if (firstRoot == secondRoot) {
            return false;
        }

        if (rank[firstRoot] < rank[secondRoot]) {
            parent[firstRoot] = secondRoot;
        } else if (rank[firstRoot] > rank[secondRoot]) {
            parent[secondRoot] = firstRoot;
        } else {
            parent[secondRoot] = firstRoot;
            rank[firstRoot]++;
        }

        return true;
    }

    private int find(int vertex) {
        if (parent[vertex] != vertex) {
            parent[vertex] = find(parent[vertex]);
        }

        return parent[vertex];
    }
}

public record Edge(int from, int to, int weight) {
    public static Edge fromRow(int[] edgeRow) {
        if (edgeRow == null || edgeRow.length != 3) {
            throw new IllegalArgumentException("Each edge must contain exactly 3 values: from, to, weight.");
        }

        return new Edge(edgeRow[0], edgeRow[1], edgeRow[2]);
    }
}

import java.util.ArrayList;
import java.util.List;

public record MstResult(int vertexCount, int totalWeight, List<Edge> edges) {
    public MstResult {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("Vertex count cannot be negative.");
        }

        edges = List.copyOf(edges);

        if (edges.size() > requiredEdgeCount(vertexCount)) {
            throw new IllegalArgumentException("Result contains too many edges for the given vertex count.");
        }
    }

    public static Builder builderFor(int vertexCount) {
        return new Builder(vertexCount);
    }

    public boolean spansAllVertices() {
        return edges.size() == requiredEdgeCount(vertexCount);
    }

    public int requiredEdgeCount() {
        return requiredEdgeCount(vertexCount);
    }

    private static int requiredEdgeCount(int vertexCount) {
        return vertexCount == 0 ? 0 : vertexCount - 1;
    }

    public static final class Builder {
        private final int vertexCount;
        private final int targetEdgeCount;
        private final ArrayList<Edge> selectedEdges;
        private int totalWeight;

        private Builder(int vertexCount) {
            if (vertexCount < 0) {
                throw new IllegalArgumentException("Vertex count cannot be negative.");
            }

            this.vertexCount = vertexCount;
            targetEdgeCount = requiredEdgeCount(vertexCount);
            selectedEdges = new ArrayList<>(targetEdgeCount);
        }

        public void include(Edge edge) {
            if (isComplete()) {
                throw new IllegalStateException("Cannot include more edges after the spanning tree is complete.");
            }

            selectedEdges.add(edge);
            totalWeight += edge.weight();
        }

        public boolean isComplete() {
            return selectedEdges.size() == targetEdgeCount;
        }

        public MstResult build() {
            return new MstResult(vertexCount, totalWeight, selectedEdges);
        }
    }
}

